.converter-card {
    background: var(--card-bg);
    border-radius: 20px;
    padding: 2rem;
    max-width: 500px;
    margin: 0 auto;
    box-shadow: 0 10px 20px rgba(0, 0, 0, 0.3);
  }

  .input-group {
    margin-bottom: 1.5rem;
  }
  :root {
    --primary-color: #00ff9d;
    --bg-color: #1a1a1a;
    --card-bg: #2a2a2a;
    --text-color: #ffffff;
  }

  * {
    box-sizing: border-box;
    margin: 0;
    padding: 0;
  }

  body {
    font-family: system-ui, -apple-system, sans-serif;
    background-color: var(--bg-color);
    color: var(--text-color);
    min-height: 100vh;
    line-height: 1.6;
  }

  .container {
    max-width: 1200px;
    margin: 0 auto;
    padding: 2rem;
  }

  header {
    text-align: center;
    margin-bottom: 3rem;
    padding: 1rem;
    border-bottom: 2px solid var(--primary-color);
  }

  header h1 {
    font-size: 2.5rem;
    color: var(--primary-color);
    margin-bottom: 0.5rem;
  }

  header h2 {
    font-size: 1.5rem;
    opacity: 0.8;
  }

  .tools-grid {
    display: grid;
    grid-template-columns: repeat(auto-fit, minmax(150px, 1fr));
    gap: 1.5rem;
    margin-bottom: 3rem;
  }

  .tool-card {
    background: var(--card-bg);
    border-radius: 12px;
    padding: 1.5rem;
    text-align: center;
    text-decoration: none;
    color: var(--text-color);
    transition: transform 0.3s ease, box-shadow 0.3s ease;
    border: 1px solid rgba(255, 255, 255, 0.1);
  }

  .tool-card:hover {
    transform: translateY(-5px);
    box-shadow: 0 5px 15px rgba(0, 255, 157, 0.2);
  }

  .tool-card img {
    width: 40px;
    height: 40px;
    margin-bottom: 1rem;
  }

  .tool-card span {
    display: block;
    font-size: 1rem;
  }

  .trivia-section {
    background: var(--card-bg);
    border-radius: 12px;
    padding: 2rem;
    margin-top: 2rem;
    border: 1px solid rgba(255, 255, 255, 0.1);
  }

  .trivia-section h3 {
    color: var(--primary-color);
    margin-bottom: 1rem;
    text-align: center;
  }

  #trivia-content {
    transition: opacity 0.3s ease;
  }

  .trivia-nav {
    display: flex;
    justify-content: center;
    align-items: center;
    gap: 1rem;
    margin-top: 1rem;
  }

  .trivia-nav button {
    background: none;
    border: none;
    color: var(--primary-color);
    font-size: 1.5rem;
    cursor: pointer;
    padding: 0.5rem;
    transition: opacity 0.3s ease;
  }

  .trivia-nav button:hover {
    opacity: 0.8;
  }

  #trivia-dots {
    display: flex;
    gap: 0.5rem;
  }

  .dot {
    width: 8px;
    height: 8px;
    border-radius: 50%;
    background: rgba(255, 255, 255, 0.3);
    cursor: pointer;
    transition: background-color 0.3s ease;
  }

  .dot.active {
    background: var(--primary-color);
  }

  @media (max-width: 768px) {
    .container {
      padding: 1rem;
    }

    .tools-grid {
      grid-template-columns: repeat(auto-fit, minmax(120px, 1fr));
      gap: 1rem;
    }

    .tool-card {
      padding: 1rem;
    }

    .tool-card img {
      width: 30px;
      height: 30px;
    }
  }
  .input-group label {
    display: block;
    margin-bottom: 0.5rem;
    color: var(--primary-color);
    font-size: 1.1rem;
  }

  .input-with-unit {
    display: flex;
    gap: 0.5rem;
  }

  .input-with-unit input {
    flex: 1;
    background: #1a1a1a;
    border: 1px solid #333;
    color: var(--text-color);
    padding: 0.8rem;
    border-radius: 10px;
    font-size: 1rem;
  }

  .input-with-unit select {
    width: 120px;
    background: #333;
    border: none;
    color: var(--text-color);
    padding: 0.8rem;
    border-radius: 10px;
    font-size: 1rem;
    cursor: pointer;
  }

  .convert-btn {
    width: 100%;
    background: var(--primary-color);
    color: var(--bg-color);
    border: none;
    padding: 1rem;
    border-radius: 10px;
    font-size: 1.1rem;
    cursor: pointer;
    transition: background-color 0.3s ease;
  }

  .convert-btn:hover {
    background: #00cc7d;
  }

  .swap-btn {
    width: 100%;
    background: #333;
    color: var(--text-color);
    border: none;
    padding: 0.5rem;
    border-radius: 10px;
    margin: 1rem 0;
    cursor: pointer;
    transition: background-color 0.3s ease;
  }

  .swap-btn:hover {
    background: #444;
  }

  .result {
    margin-top: 1.5rem;
    padding: 1rem;
    background: #1a1a1a;
    border-radius: 10px;
    display: flex;
    justify-content: space-between;
    align-items: center;
  }

  .result-label {
    color: var(--primary-color);
  }

  .result-value {
    font-size: 1.2rem;
    font-weight: bold;
  }

  .back-link {
    color: var(--primary-color);
    text-decoration: none;
    display: inline-block;
    margin-top: 1rem;
    font-size: 1.1rem;
  }

  .back-link:hover {
    text-decoration: underline;
  }

  .bmi-scale {
    margin-top: 2rem;
    display: grid;
    grid-template-columns: repeat(4, 1fr);
    gap: 1rem;
    text-align: center;
  }

  .scale-item {
    background: #1a1a1a;
    padding: 0.8rem;
    border-radius: 10px;
  }

  .scale-label {
    display: block;
    color: var(--primary-color);
    font-size: 0.9rem;
    margin-bottom: 0.3rem;
  }

  .scale-value {
    font-size: 0.8rem;
  }

  @media (max-width: 768px) {
    .converter-card {
      padding: 1.5rem;
    }

    .input-with-unit {
      flex-direction: column;
    }

    .input-with-unit select {
      width: 100%;
    }

    .bmi-scale {
      grid-template-columns: repeat(2, 1fr);
    }
  }

