function convertToC(value, unit) {
    switch (unit) {
        case 'c':
            return value;
        case 'f':
            return (value - 32) * 5 / 9;
        case 'k':
            return value - 273.15;
        default:
            return 0;
    }
  }

  function convertFromC(value, unit) {
    switch (unit) {
        case 'c':
            return value;
        case 'f':
            return (value * 9 / 5) + 32;
        case 'k':
            return value + 273.15;
        default:
